+  const doron = await corpus.ensureFigure({ displayName: 'דורון בן־שחר', role: 'פרשן כלכלי (דמות לדוגמה)' });
+  const neta = await corpus.ensureFigure({ displayName: 'נטע קרליבך', role: 'עיתונאית (דמות לדוגמה)' });
