+    ordinal: 0, figureId: ilana.id, language: 'he', saidAt: '2025-01-20',
+    quote: 'מצוקת הדיור היא בעיה תקציבית. בלי תקציב ייעודי לא נפתור אותה.',
+    context: 'טור אורח.', topics: ['דיור', 'תקציב'],
