export default {
  title: 'a withdrawn figure leaves the listings and still resolves by id',
  async run() {
    const corpus = emptyCorpus();
    const kept = await corpus.ensureFigure({ displayName: 'דמות ראשונה לדוגמה', role: 'דמות לדוגמה' });
