+      .prepare('SELECT * FROM sources WHERE source_module = ? AND external_key = ?')
+      .bind(sourceModule, externalKey)
+      .first<Row>();
+    return row ? toSource(row) : null;
+  }
+
+  async getSource(id: string): Promise<Source | null> {
