+             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
+          )
+          .bind(id, item.figureId, item.quote, item.language, item.saidAt, item.context, sourceId, topics, item.ordinal)
+          .run();
+      }
+      await this.#reindex(id, [item.quote, item.context ?? '', item.topics.join(' ')].join(' '));
