/* The warm-editorial design system, written in logical properties throughout: the same
   sheet lays the page out right-to-left for Hebrew and left-to-right for English, because
   direction follows the content's language rather than a site-wide setting. */
@import './fonts.GENERATED.css';

:root {
  --paper: #f6f3ec;
  --card: #fdfcf8;
  --tint: #f1ede2;
  --ink: #201e19;
  --muted: #6e685c;
  --rule: #e2dccc;
  --oxide: #9b2c20;
  --oxide-deep: #6e1d14;
  --oxide-light: #d98a80;
  --amber: #a97a1f;

  --serif: 'Frank Ruhl Libre', Georgia, 'Times New Roman', serif;
  --sans: 'Heebo', 'Helvetica Neue', Arial, sans-serif;

  --page: 1120px;
  --gap: 24px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--oxide);
  text-decoration: none;
}

a:hover {
  color: var(--oxide-deep);
  text-decoration: underline;
}

.page {
  max-width: var(--page);
  margin: 0 auto;
  padding: 0 32px;
}

/* ---- chrome ---------------------------------------------------------------- */

.masthead {
  border-block-end: 1px solid var(--ink);
}

.masthead__inner {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--gap);
  padding: 20px 0 12px;
}

.masthead__rule {
  border-block-start: 2px solid var(--ink);
  height: 3px;
}

.wordmark {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.wordmark__hebrew {
  font-family: var(--serif);
  font-size: 30px;
  line-height: 1;
}

.wordmark__stem {
  font-weight: 800;
  color: var(--oxide);
}

.wordmark__rest {
  font-weight: 400;
  color: var(--ink);
}

.wordmark__latin {
  font-size: 11px;
  letter-spacing: 2px;
  color: var(--muted);
}

.masthead__nav {
  display: flex;
  gap: 20px;
  font-size: 14px;
  font-weight: 500;
}

.masthead__nav a {
  color: var(--ink);
}

.colophon {
  margin-block-start: 64px;
  background: var(--ink);
  color: var(--paper);
}

.colophon a {
  color: var(--oxide-light);
}

.colophon__inner {
  display: flex;
  flex-wrap: wrap;
  gap: var(--gap);
  justify-content: space-between;
  padding: 28px 0;
  font-size: 13px;
  color: #b8b2a4;
}

/* ---- headings and text ------------------------------------------------------ */

.hero {
  padding: 48px 0 32px;
}

.hero__title {
  font-family: var(--serif);
  font-size: 46px;
  font-weight: 700;
  line-height: 1.2;
  margin: 0 0 12px;
}

.hero__lede {
  font-size: 17px;
  color: var(--muted);
  margin: 0;
  max-width: 44em;
}

.section {
  margin-block-start: 44px;
}

.section__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  border-block-end: 1px solid var(--ink);
  padding-block-end: 8px;
  margin-block-end: 20px;
}

.section__title {
  font-family: var(--serif);
  font-size: 22px;
  font-weight: 700;
  margin: 0;
}

.section__note {
  font-size: 13px;
  color: var(--muted);
}

.page-title {
  font-family: var(--serif);
  font-size: 34px;
  font-weight: 700;
  line-height: 1.25;
  margin: 0 0 8px;
}

.quote {
  font-family: var(--serif);
  font-size: 20px;
  line-height: 1.55;
  margin: 0;
}

.meta {
  font-size: 13px;
  color: var(--muted);
}

.prose {
  max-width: 46em;
}

.prose p {
  margin: 0 0 16px;
}

.prose h2 {
  font-family: var(--serif);
  font-size: 22px;
  margin: 32px 0 10px;
}

/* ---- search ----------------------------------------------------------------- */

.search {
  display: flex;
  gap: 10px;
  max-width: 620px;
}

.search__input {
  flex-grow: 1;
  font-family: var(--sans);
  font-size: 16px;
  padding: 12px 14px;
  border: 1.5px solid var(--ink);
  background: var(--card);
  color: var(--ink);
}

.search__input::placeholder {
  color: var(--muted);
}

.search__button {
  font-family: var(--sans);
  font-size: 15px;
  font-weight: 700;
  padding: 12px 22px;
  border: 1.5px solid var(--oxide);
  background: var(--oxide);
  color: var(--paper);
  cursor: pointer;
}

mark {
  background: #f4e2c8;
  color: inherit;
  padding: 0 2px;
}

/* ---- cards ------------------------------------------------------------------ */

.card {
  background: var(--card);
  border: 1px solid var(--rule);
  padding: 20px 22px;
}

.card--flagged {
  border-inline-start: 3px solid var(--oxide);
}

.card__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-block-end: 10px;
}

.stack {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.badge {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.4px;
  padding: 4px 8px;
  background: var(--oxide);
  color: var(--paper);
  white-space: nowrap;
}

.badge--shift {
  background: var(--amber);
}

.chip {
  font-size: 12px;
  color: var(--muted);
  border: 1px solid var(--rule);
  padding: 3px 9px;
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.stat {
  display: flex;
  flex-direction: column;
}

.stat__value {
  font-family: var(--serif);
  font-size: 28px;
  font-weight: 700;
  line-height: 1.1;
}

.stat__label {
  font-size: 12px;
  color: var(--muted);
}

.stats {
  display: flex;
  gap: 36px;
  border-block: 1px solid var(--rule);
  padding: 16px 0;
  margin-block: 20px;
}

/* ---- the then / but / now pair ---------------------------------------------- */

.pair {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: stretch;
  gap: 0;
}

.pair__side {
  background: var(--card);
  border: 1.5px solid var(--ink);
  padding: 22px 24px;
}

.pair__side--now {
  border-color: var(--oxide);
}

.pair__when {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-block-end: 10px;
}

.pair__label {
  font-size: 12px;
  font-weight: 800;
  color: var(--muted);
}

.pair__side--now .pair__label {
  color: var(--oxide);
}

.pair__date {
  font-size: 13px;
  font-weight: 700;
}

.mark {
  align-self: center;
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--oxide);
  color: var(--paper);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--serif);
  font-size: 20px;
  box-shadow: 0 0 0 8px var(--paper);
  margin: 0 -20px;
  z-index: 1;
}

.rationale {
  background: var(--tint);
  border: 1px solid var(--rule);
  padding: 18px 22px;
  margin-block-start: 24px;
}

.rationale__title {
  font-family: var(--serif);
  font-size: 19px;
  font-weight: 700;
  margin: 0 0 8px;
}

.notice {
  border-inline-start: 3px solid var(--amber);
  background: var(--tint);
  padding: 12px 16px;
  font-size: 14px;
  margin-block-end: 20px;
}

