.ltr {
  display: inline-block;
  direction: ltr;
  unicode-bidi: isolate;
}

.empty {
  color: var(--muted);
  padding: 24px 0;
}

@media (max-width: 900px) {
  .page {
    padding: 0 20px;
  }

  .grid {
    grid-template-columns: 1fr;
  }

  .hero__title {
    font-size: 32px;
  }

  /* At phone width the two statements stack, and the mark sits between them. */
  .pair {
    grid-template-columns: 1fr;
  }

  .mark {
    margin: -20px auto;
    width: 56px;
    height: 56px;
    font-size: 18px;
  }

  .stats {
    gap: 24px;
    flex-wrap: wrap;
  }
}

