.wordmark__hebrew {
  font-family: var(--serif);
  font-size: 30px;
  line-height: 1;
}

.wordmark__stem {
  font-weight: 800;
  color: var(--oxide);
}

.wordmark__rest {
  font-weight: 400;
  color: var(--ink);
