+  font-size: 13px;
+  font-weight: 700;
+}
+
+.mark {
+  align-self: center;
+  width: 64px;
+  height: 64px;
+  border-radius: 50%;
+  background: var(--oxide);
+  color: var(--paper);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-family: var(--serif);
+  font-size: 20px;
+  box-shadow: 0 0 0 8px var(--paper);
+  margin: 0 -20px;
+  z-index: 1;
+}
+
+.rationale {
+  background: var(--tint);
+  border: 1px solid var(--rule);
+  padding: 18px 22px;
+  margin-block-start: 24px;
+}
+
+.rationale__title {
+  font-family: var(--serif);
+  font-size: 19px;
+  font-weight: 700;
+  margin: 0 0 8px;
+}
+
+.notice {
+  border-inline-start: 3px solid var(--amber);
+  background: var(--tint);
+  padding: 12px 16px;
+  font-size: 14px;
+  margin-block-end: 20px;
+}
+
+/* Latin runs inside Hebrew text — an id, a model name — keep their own direction. */
+.ltr {
+  display: inline-block;
+  direction: ltr;
+  unicode-bidi: isolate;
+}
+
+.empty {
+  color: var(--muted);
+  padding: 24px 0;
+}
+
+@media (max-width: 900px) {
+  .page {
+    padding: 0 20px;
+  }
+
+  .grid {
+    grid-template-columns: 1fr;
+  }
+
+  .hero__title {
+    font-size: 32px;
+  }
+
+  /* At phone width the two statements stack, and the mark sits between them. */
+  .pair {
+    grid-template-columns: 1fr;
+  }
+
+  .mark {
+    margin: -20px auto;
+    width: 56px;
+    height: 56px;
+    font-size: 18px;
+  }
+
+  .stats {
+    gap: 24px;
+    flex-wrap: wrap;
+  }
+}

